std::string image_word_hex(const std::bitset<256>& bits){
    std::string out(64,'0');
    for(int i=0;i<64;++i){
        unsigned v=0;
        for(int b=0;b<4;++b) v |= bits[4*i+b] ? (1u<<b) : 0u;
        out[63-i]="0123456789abcdef"[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text){
    if(text.size()!=64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for(int i=0;i<64;++i){
        char c=text[63-i];
        unsigned v;
        if(c>='0'&&c<='9') v=static_cast<unsigned>(c-'0');
        else if(c>='a'&&c<='f') v=static_cast<unsigned>(c-'a'+10);
        else throw std::runtime_error("word hex");
        for(int b=0;b<4;++b) out[4*i+b]=(v>>b)&1u;
    }
    return out;
}

namespace {

const uint32_t BMP_NULL = 4194303u;
const uint32_t HOP_MAX = 4194302u;

struct OwnerSpec {
    int origin;
    unsigned min_length;
    unsigned max_length;
    uint64_t key;
};

struct LocalInfo {
    uint16_t pos;
    uint8_t local_length;
    uint16_t value;
    uint32_t hop;
};

struct ParsedNode {
    int stage = 0;
    uint32_t cell = 0;
    uint8_t type = 0;
    uint8_t depth = 0;
    ip6_t region{0,0};
    uint32_t bmp = BMP_NULL;
    bool bulk_parent = false;

    uint32_t bitmap_id = 0;
    uint32_t ni_base = 0;
    uint64_t bitmap = 0;
    std::vector<LocalInfo> locals;

    uint64_t bulk_bitmap = 0;
    uint32_t bulk_base = 0;
    uint8_t bulk_stage = 0;
    int direct_count = 0;
    int bulk_count = 0;

    std::vector<IPPrefix> inlines;
    std::vector<int> children;
};

uint64_t record_field(const ImageData& d, int stage, uint32_t cell,
                      int offset, int width) {
    const std::bitset<256>& word = d.banks[stage][cell >> 1];
    int base = (cell & 1u) ? 128 : 0;
    uint64_t value = 0;
    for (int i = 0; i < width; ++i)
        value |= static_cast<uint64_t>(word[base + offset + i]) << i;
    return value;
}

bool cell_is_zero(const ImageData& d, int stage, uint32_t cell) {
    const std::bitset<256>& word = d.banks[stage][cell >> 1];
    int base = (cell & 1u) ? 128 : 0;
    for (int i = 0; i < 128; ++i)
        if (word[base + i]) return false;
    return true;
}

bool exact_prefix_lookup(const std::vector<IPPrefix>& sorted,
                         uint8_t length, const ip6_t& address,
                         uint32_t& hop) {
    IPPrefix target;
    target.address = mask_ip6(address, length);
    target.length = length;
    target.hop = 0;
    auto it = std::lower_bound(sorted.begin(), sorted.end(), target,
                               prefix_entry_less);
    if (it == sorted.end()) return false;
    if (it->length != length || it->address.hi != target.address.hi ||
        it->address.lo != target.address.lo) return false;
    hop = it->hop;
    return true;
}

class ImageValidator {
public:
    ImageValidator(const ImageData& image, std::vector<IPPrefix>& decoded)
        : d_(image), decoded_(decoded), ok_(true) {}

    bool run() {
        if (!check_side_tables()) return false;
        if (!check_front_ordering()) return false;
        if (!parse_roots()) return false;
        if (!check_ni_allocation()) return false;
        if (!check_coverage()) return false;
        compute_subtree_counts();
        if (!ok_) return false;
        if (!check_types_and_counts()) return false;
        if (!normalize_and_check_prefixes()) return false;
        if (!check_front_completeness()) return false;
        if (!check_bmps()) return false;
        decoded_ = prefixes_;
        return true;
    }

private:
    const ImageData& d_;
    std::vector<IPPrefix>& decoded_;
    bool ok_;
    std::vector<ParsedNode> nodes_;
    std::unordered_map<uint64_t, int> node_at_;
    std::vector<IPPrefix> prefixes_;
    std::vector<uint8_t> pattern_used_;
    std::vector<int> subtree_count_;
    std::vector<int> subtree_memo_;

    bool bad() { ok_ = false; return false; }

    static uint64_t node_key(int stage, uint32_t cell) {
        return (static_cast<uint64_t>(stage) << 32) | cell;
    }

    bool check_side_tables() {
        if (d_.root.stage >= 0 &&
            (d_.root.stage > 10 || d_.root.cell > 131071u)) return bad();
        uint64_t total_rows = 0;
        for (int s = 0; s < RAM_NUM; ++s) {
            if (d_.cells[s] > 131072u) return bad();
            uint64_t expected_rows = (static_cast<uint64_t>(d_.cells[s]) + 1) / 2;
            if (d_.banks[s].size() != expected_rows) return bad();
            if (d_.banks[s].size() > 65536u) return bad();
            total_rows += d_.banks[s].size();
        }
        if (total_rows > 65536u) return bad();
        if (d_.bitmaps.size() > 8193u) return bad();
        for (size_t i = 0; i < d_.bitmaps.size(); ++i) {
            if (d_.bitmaps[i] & 1ULL) return bad();
            if (i && !(d_.bitmaps[i - 1] < d_.bitmaps[i])) return bad();
        }
        if (d_.nexthops.size() > 8192u) return bad();
        for (uint32_t h : d_.nexthops)
            if (h > HOP_MAX) return bad();
        pattern_used_.assign(d_.bitmaps.size(), 0);
        return true;
    }

    bool check_front_ordering() {
        if (d_.front16.size() > 4096u || d_.front64.size() > 4096u)
            return bad();
        for (size_t i = 0; i < d_.front16.size(); ++i) {
            const ImageLoc& loc = d_.front16[i].loc;
            if (loc.stage < 0 || loc.stage > 10 || loc.cell > 131071u)
                return bad();
            if (i && !(d_.front16[i - 1].key < d_.front16[i].key))
                return bad();
        }
        for (size_t i = 0; i < d_.front64.size(); ++i) {
            const ImageLoc& loc = d_.front64[i].loc;
            if (loc.stage < 0 || loc.stage > 10 || loc.cell > 131071u)
                return bad();
            if (i && !(d_.front64[i - 1].key < d_.front64[i].key))
                return bad();
        }
        return true;
    }

    bool parse_roots() {
        if (d_.root.stage >= 0) {
            OwnerSpec owner{0, 0, 16, 0};
            ip6_t region{0, 0};
            if (!parse_node(d_.root, owner, 0, region, false, -1))
                return false;
        }
        for (const ImageFront& f : d_.front16) {
            OwnerSpec owner{16, 17, 64, f.key};
            ip6_t region{0, 0};
            region.hi = f.key << 48;
            if (!parse_node(f.loc, owner, 16, region, false, -1))
                return false;
        }
        for (const ImageFront& f : d_.front64) {
            OwnerSpec owner{64, 65, 128, f.key};
            ip6_t region{0, 0};
            region.hi = f.key;
            if (!parse_node(f.loc, owner, 64, region, false, -1))
                return false;
        }
        return ok_;
    }

    bool decode_child(uint64_t raw, int stage, uint32_t cell,
                      uint8_t& key, ImageLoc& loc, bool& present) {
        key = static_cast<uint8_t>(raw & 0x3fu);
        unsigned child_stage = static_cast<unsigned>((raw >> 6) & 0xfu);
        uint32_t child_cell = static_cast<uint32_t>((raw >> 10) & 0x3fffffu);
        if (key == 0 && child_stage == 15 && child_cell == 0) {
            present = false;
            loc.stage = -1;
            loc.cell = 0;
            return true;
        }
        if (child_stage > 10 || child_cell > 131071u) return bad();
        if (static_cast<int>(child_stage) >= stage) return bad();
        if (child_cell >= d_.cells[child_stage]) return bad();
        present = true;
        loc.stage = static_cast<int>(child_stage);
        loc.cell = child_cell;
        return true;
    }

    bool add_prefix(const IPPrefix& p) {
        if (prefixes_.size() >= 8192u) return bad();
        prefixes_.push_back(p);
        return true;
    }

    bool validate_inline(uint64_t fragment, unsigned relative_length,
                         uint32_t hop, const OwnerSpec& owner,
                         const ParsedNode& node, IPPrefix& out) {
        if (hop == BMP_NULL) return bad();
        unsigned length;
        ip6_t address{0, 0};
        if (owner.origin == 0) {
            if (relative_length > 16u) return bad();
            length = relative_length;
            uint64_t mask = length == 0 ? 0ULL : (~0ULL << (64 - length));
            if (fragment & ~mask) return bad();
            address.hi = fragment;
            address.lo = 0;
        } else if (owner.origin == 16) {
            if (relative_length < 1u || relative_length > 48u) return bad();
            length = 16u + relative_length;
            if (fragment & 0xffffULL) return bad();
            uint64_t value48 = fragment >> 16;
            uint64_t mask = relative_length == 0 ? 0ULL :
                            (~0ULL >> (64 - relative_length));
            if (value48 & ~mask) return bad();
            address.hi = (owner.key << 48) | value48;
            address.lo = 0;
        } else {
            if (relative_length < 1u || relative_length > 64u) return bad();
            length = 64u + relative_length;
            uint64_t mask = relative_length == 64 ? ~0ULL :
                            (~0ULL >> (64 - relative_length));
            if (fragment & ~mask) return bad();
            address.hi = owner.key;
            address.lo = fragment;
        }
        if (length < owner.min_length || length > owner.max_length)
            return bad();
        address = mask_ip6(address, length);
        if (!prefix_in_region(address, length, node.region, node.depth))
            return bad();
        if (length < node.depth) return bad();
        out.address = address;
        out.length = static_cast<uint8_t>(length);
        out.hop = hop;
        return true;
    }

    bool decode_local_hop(unsigned ordinal, const ParsedNode& node,
                          uint32_t& hop) {
        if (static_cast<uint64_t>(node.ni_base) + ordinal >= d_.nexthops.size())
            return bad();
        hop = d_.nexthops[node.ni_base + ordinal];
        if (hop > HOP_MAX) return bad();
        return true;
    }

    bool parse_node(const ImageLoc& loc, const OwnerSpec& owner, int depth,
                    const ip6_t& region, bool bulk_parent, int parent_stage) {
        if (!ok_) return false;
        if (loc.stage < 0 || loc.stage > 10 || loc.cell > 131071u)
            return bad();
        if (static_cast<unsigned>(depth) > owner.max_length) return bad();
        uint32_t cell = loc.cell;
        if (cell >= d_.cells[loc.stage]) return bad();
        uint64_t nkey = node_key(loc.stage, cell);
        if (node_at_.count(nkey)) return bad();
        int type = static_cast<int>(record_field(d_, loc.stage, cell, 0, 3));
        if (type < 1 || type > 5) return bad();
        if ((type == 2 || type == 3 || type == 5) && (cell & 1u))
            return bad();
        if (bulk_parent && (cell & 1u)) return bad();

        ParsedNode node;
        node.stage = loc.stage;
        node.cell = cell;
        node.type = static_cast<uint8_t>(type);
        node.depth = static_cast<uint8_t>(depth);
        node.region = mask_ip6(region, depth);
        node.bulk_parent = bulk_parent;
        node.bmp = static_cast<uint32_t>(record_field(d_, loc.stage, cell, 3, 22));
        if (node.bmp > BMP_NULL) return bad();

        if (type == 4 || type == 5) {
            int inline_count = (type == 4) ? 1 : 2;
            int reserved_offset = (type == 4) ? 119 : 213;
            int reserved_width = (type == 4) ? 9 : 43;
            if (record_field(d_, loc.stage, cell, reserved_offset,
                             reserved_width) != 0) return bad();
            for (int i = 0; i < inline_count; ++i) {
                int off = 25 + i * 94;
                uint64_t fragment = record_field(d_, loc.stage, cell, off, 64);
                unsigned relative = static_cast<unsigned>(
                    record_field(d_, loc.stage, cell, off + 64, 8));
                uint32_t hop = static_cast<uint32_t>(
                    record_field(d_, loc.stage, cell, off + 72, 22));
                IPPrefix p;
                if (!validate_inline(fragment, relative, hop, owner, node, p))
                    return false;
                node.inlines.push_back(p);
                if (!add_prefix(p)) return false;
            }
            if (type == 5 &&
                prefix_entry_equal(node.inlines[0], node.inlines[1]))
                return bad();
        } else {
            int reserved_offset = (type == 1) ? 127 : (type == 2 ? 255 : 249);
            int reserved_width = (type == 1 || type == 2) ? 1 : 7;
            if (record_field(d_, loc.stage, cell, reserved_offset,
                             reserved_width) != 0) return bad();

            node.bitmap_id = static_cast<uint32_t>(
                record_field(d_, loc.stage, cell, 25, 16));
            node.ni_base = static_cast<uint32_t>(
                record_field(d_, loc.stage, cell, 41, 22));
            if (node.bitmap_id >= d_.bitmaps.size()) return bad();
            node.bitmap = d_.bitmaps[node.bitmap_id];
            pattern_used_[node.bitmap_id] = 1;
            int local_count = __builtin_popcountll(node.bitmap);
            if (local_count == 0) {
                if (node.ni_base != 0) return bad();
            } else {
                if (static_cast<uint64_t>(node.ni_base) +
                    static_cast<uint64_t>(local_count) > d_.nexthops.size())
                    return bad();
                unsigned ordinal = 0;
                for (int pos = 1; pos < 64; ++pos) {
                    if (((node.bitmap >> pos) & 1ULL) == 0) continue;
                    int l = 0;
                    int base = 1;
                    while (l < 5 && pos >= base * 2) {
                        ++l;
                        base *= 2;
                    }
                    int v = pos - base;
                    unsigned global_length = static_cast<unsigned>(depth) + l;
                    if (global_length < owner.min_length ||
                        global_length > owner.max_length) return bad();
                    ip6_t address = make_local_prefix(node.region, depth, l,
                                                      static_cast<uint64_t>(v));
                    address = mask_ip6(address, global_length);
                    IPPrefix p;
                    p.address = address;
                    p.length = static_cast<uint8_t>(global_length);
                    if (!decode_local_hop(ordinal++,
                                          ParsedNode{loc.stage, cell, node.type,
                                                     node.depth, node.region,
                                                     node.bmp},
                                          p.hop)) return false;
                    if (!prefix_in_region(address, global_length,
                                          node.region, depth)) return bad();
                    node.locals.push_back(LocalInfo{
                        static_cast<uint16_t>(pos),
                        static_cast<uint8_t>(l),
                        static_cast<uint16_t>(v), p.hop});
                    if (!add_prefix(p)) return false;
                }
            }
        }

        std::vector<std::pair<uint8_t, ImageLoc> > direct_children;
        int inline_children = 0;
        if (type == 1 || type == 2 || type == 3) {
            int slots = (type == 1) ? 2 : (type == 2 ? 6 : 3);
            int off0 = (type == 1 || type == 2) ? 63 : 153;
            bool saw_absent = false;
            for (int i = 0; i < slots; ++i) {
                uint64_t raw = record_field(d_, loc.stage, cell,
                                            off0 + i * 32, 32);
                uint8_t key = 0;
                ImageLoc child_loc;
                bool present = false;
                if (!decode_child(raw, loc.stage, cell, key, child_loc,
                                  present)) return false;
                if (!present) {
                    saw_absent = true;
                    continue;
                }
                if (saw_absent) return bad();
                static const uint64_t absent_record = 15ULL << 6;
                (void)absent_record;
                if (!direct_children.empty() &&
                    direct_children.back().first >= key) return bad();
                if (depth + 6 > static_cast<int>(owner.max_length))
                    return bad();
                direct_children.push_back(std::make_pair(key, child_loc));
            }
            inline_children = static_cast<int>(direct_children.size());
            if (type == 1 && inline_children > 2) return bad();
            if (type == 2 &&
                (inline_children < 3 || inline_children > 6)) return bad();
        }

        std::vector<std::pair<uint8_t, ImageLoc> > bulk_children;
        if (type == 3) {
            node.bulk_bitmap = record_field(d_, loc.stage, cell, 63, 64);
            node.bulk_base = static_cast<uint32_t>(
                record_field(d_, loc.stage, cell, 127, 22));
            node.bulk_stage = static_cast<uint8_t>(
                record_field(d_, loc.stage, cell, 149, 4));
            node.direct_count = static_cast<int>(direct_children.size());
            if (node.direct_count > 3) return bad();
            int bc = __builtin_popcountll(node.bulk_bitmap);
            node.bulk_count = bc;
            if (node.bulk_count > 0) {
                if (node.bulk_count < 4) return bad();
                if (node.bulk_stage > 10 ||
                    static_cast<int>(node.bulk_stage) >= loc.stage) return bad();
                if (node.bulk_base & 1u) return bad();
                uint64_t end = static_cast<uint64_t>(node.bulk_base) +
                               2ULL * static_cast<uint64_t>(node.bulk_count);
                if (end > d_.cells[node.bulk_stage]) return bad();
                int ordinal = 0;
                for (int key = 0; key < 64; ++key) {
                    if (((node.bulk_bitmap >> key) & 1ULL) == 0) continue;
                    for (const auto& dc : direct_children)
                        if (dc.first == key) return bad();
                    ImageLoc child_loc;
                    child_loc.stage = node.bulk_stage;
                    child_loc.cell = node.bulk_base +
                                     2u * static_cast<uint32_t>(ordinal);
                    bulk_children.push_back(std::make_pair(
                        static_cast<uint8_t>(key), child_loc));
                    ++ordinal;
                }
            }
            int total_children = node.direct_count + node.bulk_count;
            if (total_children < 7 || total_children > 64) return bad();
        }

        int index = static_cast<int>(nodes_.size());
        nodes_.push_back(node);
        node_at_[nkey] = index;
        ParsedNode& stored = nodes_[index];

        for (const auto& dc : direct_children) {
            if (depth + 6 > static_cast<int>(owner.max_length)) return bad();
            ip6_t child_region = make_local_prefix(region, depth, 6, dc.first);
            ImageLoc cl = dc.second;
            if (cl.stage >= loc.stage) return bad();
            if (cl.cell >= d_.cells[cl.stage]) return bad();
            int before = static_cast<int>(nodes_.size());
            if (!parse_node(cl, owner, depth + 6, child_region, false,
                            loc.stage)) return false;
            if (static_cast<int>(nodes_.size()) != before + 1)
                return bad();
            stored.children.push_back(static_cast<int>(nodes_.size()) - 1);
        }
        for (const auto& bc : bulk_children) {
            if (depth + 6 > static_cast<int>(owner.max_length)) return bad();
            ip6_t child_region = make_local_prefix(region, depth, 6, bc.first);
            ImageLoc cl = bc.second;
            if (cl.stage >= loc.stage) return bad();
            if (cl.cell >= d_.cells[cl.stage]) return bad();
            int before = static_cast<int>(nodes_.size());
            if (!parse_node(cl, owner, depth + 6, child_region, true,
                            loc.stage)) return false;
            if (static_cast<int>(nodes_.size()) != before + 1)
                return bad();
            stored.children.push_back(static_cast<int>(nodes_.size()) - 1);
        }
        return true;
    }

    bool check_ni_allocation() {
        std::vector<int> owner(d_.nexthops.size(), -1);
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const ParsedNode& n = nodes_[i];
            if (n.type == 4 || n.type == 5) continue;
            int count = static_cast<int>(n.locals.size());
            if (count == 0) {
                if (n.ni_base != 0) return bad();
                continue;
            }
            if (static_cast<uint64_t>(n.ni_base) +
                static_cast<uint64_t>(count) > d_.nexthops.size())
                return bad();
            for (int j = 0; j < count; ++j) {
                size_t at = static_cast<size_t>(n.ni_base) + j;
                if (owner[at] != -1) return bad();
                owner[at] = static_cast<int>(i);
            }
        }
        for (int v : owner)
            if (v == -1) return bad();
        for (uint8_t used : pattern_used_)
            if (!used) return bad();
        return true;
    }

    bool check_coverage() {
        std::vector<std::vector<uint8_t> > occupied(RAM_NUM);
        for (int s = 0; s < RAM_NUM; ++s)
            occupied[s].assign(d_.cells[s], 0);

        for (const ParsedNode& n : nodes_) {
            int extent;
            if (n.bulk_parent) extent = 2;
            else if (n.type == 1 || n.type == 4) extent = 1;
            else extent = 2;
            if (n.type == 2 || n.type == 3 || n.type == 5) {
                if (n.cell & 1u) return bad();
            }
            if (n.cell + static_cast<uint32_t>(extent) > d_.cells[n.stage])
                return bad();
            for (int j = 0; j < extent; ++j) {
                if (occupied[n.stage][n.cell + j]) return bad();
                occupied[n.stage][n.cell + j] = 1;
            }
            if (n.bulk_parent && (n.type == 1 || n.type == 4)) {
                if (n.cell + 1 >= d_.cells[n.stage]) return bad();
                if (!cell_is_zero(d_, n.stage, n.cell + 1)) return bad();
            }
        }
        for (int s = 0; s < RAM_NUM; ++s) {
            for (uint32_t c = 0; c < d_.cells[s]; ++c)
                if (!occupied[s][c]) return bad();
            if (d_.cells[s] & 1u) {
                if (d_.cells[s] >= 131072u) return bad();
                if (!cell_is_zero(d_, s, d_.cells[s])) return bad();
            }
        }
        return true;
    }

    int compute_count(int index) {
        if (!ok_) return 0;
        if (subtree_memo_[index] >= 0) return subtree_memo_[index];
        const ParsedNode& n = nodes_[index];
        int count = 0;
        if (n.type == 4) {
            count = static_cast<int>(n.inlines.size());
        } else if (n.type == 5) {
            count = static_cast<int>(n.inlines.size());
        } else {
            count = static_cast<int>(n.locals.size());
            for (int child : n.children) {
                int c = compute_count(child);
                if (!ok_) return 0;
                if (count > 8192 - c) { bad(); return 0; }
                count += c;
            }
        }
        if (count <= 0 || count > 8192) { bad(); return 0; }
        subtree_memo_[index] = count;
        return count;
    }

    void compute_subtree_counts() {
        subtree_memo_.assign(nodes_.size(), -1);
        subtree_count_.assign(nodes_.size(), 0);
        for (size_t i = 0; i < nodes_.size(); ++i)
            subtree_count_[i] = compute_count(static_cast<int>(i));
    }

    bool check_types_and_counts() {
        if (!ok_) return false;
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const ParsedNode& n = nodes_[i];
            int count = subtree_count_[i];
            int child_count = static_cast<int>(n.children.size());
            if (n.type == 4) {
                if (n.inlines.size() != 1 || count != 1 || child_count != 0)
                    return bad();
            } else if (n.type == 5) {
                if (n.inlines.size() != 2 || count != 2 || child_count != 0)
                    return bad();
                if (prefix_entry_equal(n.inlines[0], n.inlines[1])) return bad();
            } else {
                if (count < 3) return bad();
                if (n.type == 1) {
                    if (child_count < 0 || child_count > 2) return bad();
                } else if (n.type == 2) {
                    if (child_count < 3 || child_count > 6) return bad();
                } else if (n.type == 3) {
                    if (child_count < 7 || child_count > 64) return bad();
                    if (n.direct_count < 0 || n.direct_count > 3) return bad();
                    if (n.bulk_count > 0 && n.bulk_count < 4) return bad();
                    if (n.direct_count + n.bulk_count != child_count)
                        return bad();
                } else {
                    return bad();
                }
            }
        }
        return true;
    }

    bool normalize_and_check_prefixes() {
        std::sort(prefixes_.begin(), prefixes_.end(), prefix_entry_less);
        for (size_t i = 0; i < prefixes_.size(); ++i) {
            IPPrefix normalized = make_prefix(prefixes_[i].address,
                                              prefixes_[i].length,
                                              prefixes_[i].hop);
            if (normalized.address.hi != prefixes_[i].address.hi ||
                normalized.address.lo != prefixes_[i].address.lo)
                return bad();
            if (prefixes_[i].hop > HOP_MAX) return bad();
            if (i && prefix_entry_equal(prefixes_[i - 1], prefixes_[i]))
                return bad();
        }
        if (prefixes_.size() > 8192u) return bad();
        return true;
    }

    bool check_front_completeness() {
        bool need_root = false;
        std::set<uint64_t> keys16, keys64;
        for (const IPPrefix& p : prefixes_) {
            if (p.length <= 16) {
                need_root = true;
            } else if (p.length <= 64) {
                keys16.insert(p.address.hi >> 48);
            } else {
                keys64.insert(p.address.hi);
            }
        }
        bool have_root = d_.root.stage >= 0;
        if (need_root != have_root) return bad();
        if (keys16.size() != d_.front16.size()) return bad();
        size_t i = 0;
        for (uint64_t key : keys16) {
            if (d_.front16[i].key != key) return bad();
            ++i;
        }
        if (keys64.size() != d_.front64.size()) return bad();
        i = 0;
        for (uint64_t key : keys64) {
            if (d_.front64[i].key != key) return bad();
            ++i;
        }
        return true;
    }

    bool check_bmps() {
        for (const ParsedNode& n : nodes_) {
            uint32_t expected = BMP_NULL;
            for (int k = static_cast<int>(n.depth); k >= 0; --k) {
                ip6_t masked = mask_ip6(n.region, static_cast<unsigned>(k));
                uint32_t hop = 0;
                if (exact_prefix_lookup(prefixes_, static_cast<uint8_t>(k),
                                        masked, hop)) {
                    expected = hop;
                    break;
                }
            }
            if (n.bmp != expected) return bad();
        }
        return true;
    }
};

bool validate_image_data(const ImageData& d, std::vector<IPPrefix>& decoded) {
    ImageValidator validator(d, decoded);
    return validator.run();
}

// ---------------------------------------------------------------------------
// Compact image construction
// ---------------------------------------------------------------------------

struct BuildNode {
    uint8_t type = 0;
    int owner_origin = 0;
    unsigned owner_max = 0;
    int depth = 0;
    ip6_t region{0, 0};
    uint32_t bmp = BMP_NULL;

    uint32_t bitmap_id = 0;
    uint32_t ni_base = 0;
    uint64_t bitmap = 0;
    std::vector<LocalInfo> locals;

    std::vector<IPPrefix> inlines;
    std::vector<BuildNode*> children;
    std::vector<uint8_t> child_keys;
    int direct_count = 0;
    int bulk_count = 0;
    uint64_t bulk_bitmap = 0;
    uint32_t bulk_base = 0;
    uint8_t bulk_stage = 0;

    int height = 0;
    uint8_t stage = 0;
    uint32_t cell = 0;
    bool bulk_parent = false;
};

struct BulkBucket {
    BuildNode* parent = nullptr;
    uint8_t stage = 0;
    std::vector<BuildNode*> children;
};

class ImageBuilder {
public:
    ImageBuilder(const std::vector<IPPrefix>& prefixes) : prefixes_(prefixes) {}

    ImageData run() {
        ImageData out;
        std::vector<IPPrefix> root0;
        std::map<uint64_t, std::vector<IPPrefix> > groups16, groups64;
        for (const IPPrefix& p : prefixes_) {
            IPPrefix n = make_prefix(p.address, p.length, p.hop);
            if (n.length <= 16) root0.push_back(n);
            else if (n.length <= 64)
                groups16[n.address.hi >> 48].push_back(n);
            else
                groups64[n.address.hi].push_back(n);
        }
        std::sort(root0.begin(), root0.end(), prefix_entry_less);
        if (!root0.empty()) {
            BuildNode* root = build_subtree(root0, 0, 0, 16);
            out.root.stage = root->stage;
            out.root.cell = root->cell;
        }
        for (auto& item : groups16) {
            std::sort(item.second.begin(), item.second.end(), prefix_entry_less);
            BuildNode* root = build_subtree(item.second, 16, 16, 64);
            ImageFront front;
            front.key = item.first;
            front.loc.stage = root->stage;
            front.loc.cell = root->cell;
            out.front16.push_back(front);
        }
        for (auto& item : groups64) {
            std::sort(item.second.begin(), item.second.end(), prefix_entry_less);
            BuildNode* root = build_subtree(item.second, 64, 64, 128);
            ImageFront front;
            front.key = item.first;
            front.loc.stage = root->stage;
            front.loc.cell = root->cell;
            out.front64.push_back(front);
        }
        assign_heights_and_stages();
        assign_cells();
        assign_bitmap_ids_and_ni();
        fill_nexthops();
        fill_banks(out);
        return out;
    }

private:
    const std::vector<IPPrefix>& prefixes_;
    std::vector<BuildNode*> nodes_;

    BuildNode* new_node(int depth, int origin, unsigned max_length,
                        const ip6_t& region) {
        BuildNode* n = new BuildNode();
        n->depth = depth;
        n->owner_origin = origin;
        n->owner_max = max_length;
        n->region = mask_ip6(region, depth);
        nodes_.push_back(n);
        return n;
    }

    BuildNode* build_subtree(const std::vector<IPPrefix>& items, int depth,
                             int origin, unsigned max_length) {
        ip6_t region = mask_ip6(items[0].address, depth);
        BuildNode* node = new_node(depth, origin, max_length, region);
        if (items.size() == 1) {
            node->type = 4;
            node->inlines.push_back(items[0]);
            return node;
        }
        if (items.size() == 2) {
            node->type = 5;
            node->inlines.push_back(items[0]);
            node->inlines.push_back(items[1]);
            return node;
        }

        std::vector<IPPrefix> local;
        std::map<uint8_t, std::vector<IPPrefix> > outer;
        bool can_have_children =
            depth + 6 <= static_cast<int>(max_length);
        for (const IPPrefix& p : items) {
            if (!can_have_children ||
                p.length < static_cast<unsigned>(depth + 6)) {
                local.push_back(p);
            } else {
                uint8_t key = static_cast<uint8_t>(
                    extract_prefix_bits(p.address, depth, 6));
                outer[key].push_back(p);
            }
        }
        uint64_t bitmap = 0;
        for (const IPPrefix& p : local) {
            int l = static_cast<int>(p.length) - depth;
            int v = static_cast<int>(extract_prefix_bits(p.address, depth, l));
            int pos = (1 << l) + v;
            bitmap |= 1ull << pos;
            node->locals.push_back(LocalInfo{
                static_cast<uint16_t>(pos), static_cast<uint8_t>(l),
                static_cast<uint16_t>(v), p.hop});
        }
        std::sort(node->locals.begin(), node->locals.end(),
                  [](const LocalInfo& a, const LocalInfo& b) {
                      return a.pos < b.pos;
                  });
        node->bitmap = bitmap;
        for (const auto& item : outer) {
            node->child_keys.push_back(item.first);
            node->children.push_back(build_subtree(item.second, depth + 6,
                                                   origin, max_length));
        }
        int child_count = static_cast<int>(node->children.size());
        if (child_count <= 2) node->type = 1;
        else if (child_count <= 6) node->type = 2;
        else node->type = 3;
        if (node->type == 3) {
            node->direct_count = std::min(3, child_count);
            node->bulk_count = child_count - node->direct_count;
            for (int i = node->direct_count; i < child_count; ++i) {
                node->bulk_bitmap |= 1ull << node->child_keys[i];
            }
        }
        return node;
    }

    int compute_height(BuildNode* node) {
        if (node->type == 4 || node->type == 5) {
            node->height = 0;
            return 0;
        }
        int h = 0;
        for (BuildNode* c : node->children)
            h = std::max(h, compute_height(c) + 1);
        node->height = h;
        return h;
    }

    void assign_heights_and_stages() {
        for (BuildNode* n : nodes_)
            if (n->type == 4 || n->type == 5) n->height = 0;
        // compute_height is idempotent; use the first node as a forest entry.
        // Every node belongs to exactly one root tree, and roots are in nodes_.
        for (BuildNode* n : nodes_) {
            if (n->height == 0 && n->type != 4 && n->type != 5)
                compute_height(n);
        }
        // The loop above can miss a root whose height was already set by an
        // earlier call; that is harmless. Recompute from all leaves upward by
        // using each tree's root (a node with no parent).
        std::set<BuildNode*> is_child;
        for (BuildNode* n : nodes_)
            for (BuildNode* c : n->children) is_child.insert(c);
        for (BuildNode* n : nodes_)
            if (!is_child.count(n)) compute_height(n);

        for (BuildNode* n : nodes_) n->stage = static_cast<uint8_t>(n->height);
        // TYPE3 bulk children share one lower stage. Raising them to the
        // largest child height preserves every parent/child ordering.
        for (BuildNode* n : nodes_) {
            if (n->type != 3 || n->bulk_count == 0) continue;
            int common = 0;
            for (int i = n->direct_count;
                 i < static_cast<int>(n->children.size()); ++i)
                common = std::max(common, n->children[i]->height);
            for (int i = n->direct_count;
                 i < static_cast<int>(n->children.size()); ++i) {
                n->children[i]->stage = static_cast<uint8_t>(common);
                n->children[i]->bulk_parent = true;
            }
        }
    }

    void assign_cells() {
        std::vector<BulkBucket> buckets;
        for (BuildNode* n : nodes_) {
            if (n->type != 3 || n->bulk_count == 0) continue;
            BulkBucket b;
            b.parent = n;
            b.stage = n->children[n->direct_count]->stage;
            for (int i = n->direct_count;
                 i < static_cast<int>(n->children.size()); ++i)
                b.children.push_back(n->children[i]);
            buckets.push_back(b);
        }
        for (int stage = 0; stage < RAM_NUM; ++stage) {
            uint32_t cursor = 0;
            for (BulkBucket& b : buckets) {
                if (b.stage != stage) continue;
                b.parent->bulk_base = cursor;
                b.parent->bulk_stage = static_cast<uint8_t>(stage);
                for (size_t i = 0; i < b.children.size(); ++i) {
                    b.children[i]->cell = cursor + 2u * static_cast<uint32_t>(i);
                    cursor += 2;
                }
            }
            for (BuildNode* n : nodes_) {
                if (n->stage != stage || n->bulk_parent) continue;
                if (n->type == 2 || n->type == 3 || n->type == 5) {
                    n->cell = cursor;
                    cursor += 2;
                }
            }
            for (BuildNode* n : nodes_) {
                if (n->stage != stage || n->bulk_parent) continue;
                if (n->type == 1 || n->type == 4) {
                    n->cell = cursor;
                    cursor += 1;
                }
            }
        }
    }

    void assign_bitmap_ids_and_ni() {
        std::set<uint64_t> patterns;
        for (BuildNode* n : nodes_) {
            if (n->type == 1 || n->type == 2 || n->type == 3)
                patterns.insert(n->bitmap);
        }
        bitmaps_.assign(patterns.begin(), patterns.end());
        uint32_t ni_cursor = 0;
        for (BuildNode* n : nodes_) {
            if (!(n->type == 1 || n->type == 2 || n->type == 3)) continue;
            n->bitmap_id = static_cast<uint32_t>(
                std::lower_bound(bitmaps_.begin(), bitmaps_.end(), n->bitmap) -
                bitmaps_.begin());
            if (n->locals.empty()) n->ni_base = 0;
            else {
                n->ni_base = ni_cursor;
                ni_cursor += static_cast<uint32_t>(n->locals.size());
            }
        }
    }

    void fill_nexthops() {
        uint32_t total = 0;
        for (BuildNode* n : nodes_) {
            if (!(n->type == 1 || n->type == 2 || n->type == 3)) continue;
            total += static_cast<uint32_t>(n->locals.size());
        }
        nexthops_.clear();
        nexthops_.reserve(total);
        for (BuildNode* n : nodes_) {
            if (!(n->type == 1 || n->type == 2 || n->type == 3)) continue;
            for (const LocalInfo& l : n->locals)
                nexthops_.push_back(l.hop);
        }
    }

    uint32_t bmp_for(const BuildNode* node,
                     const std::vector<IPPrefix>& sorted_prefixes) const {
        for (int k = node->depth; k >= 0; --k) {
            ip6_t masked = mask_ip6(node->region, static_cast<unsigned>(k));
            uint32_t hop = 0;
            if (exact_prefix_lookup(sorted_prefixes,
                                    static_cast<uint8_t>(k), masked, hop))
                return hop;
        }
        return BMP_NULL;
    }

    static void set_bits(std::bitset<256>& word, int base, int offset,
                         int width, uint64_t value) {
        for (int i = 0; i < width; ++i)
            word.set(base + offset + i, ((value >> i) & 1ULL) != 0);
    }

    static uint32_t pack_child(uint8_t key, const BuildNode* child) {
        uint32_t out = 0;
        out |= static_cast<uint32_t>(key);
        out |= static_cast<uint32_t>(child->stage & 0xfu) << 6;
        out |= static_cast<uint32_t>(child->cell & 0x3fffffu) << 10;
        return out;
    }

    static const uint32_t ABSENT_CHILD = 15u << 6;

    static void pack_inline(std::bitset<256>& word, int base, int offset,
                            const IPPrefix& p, int origin) {
        uint64_t fragment = 0;
        unsigned relative = 0;
        if (origin == 0) {
            fragment = p.address.hi;
            relative = p.length;
        } else if (origin == 16) {
            fragment = (p.address.hi & 0x0000ffffffffffffULL) << 16;
            relative = static_cast<unsigned>(p.length) - 16u;
        } else {
            fragment = p.address.lo;
            relative = static_cast<unsigned>(p.length) - 64u;
        }
        set_bits(word, base, offset, 64, fragment);
        set_bits(word, base, offset + 64, 8, relative);
        set_bits(word, base, offset + 72, 22, p.hop);
    }

    void pack_node(ImageData& out, std::bitset<256>& word,
                   const BuildNode* n) const {
        int base = (n->cell & 1u) ? 128 : 0;
        set_bits(word, base, 0, 3, n->type);
        set_bits(word, base, 3, 22, n->bmp);
        if (n->type == 4 || n->type == 5) {
            pack_inline(word, base, 25, n->inlines[0], n->owner_origin);
            if (n->type == 5)
                pack_inline(word, base, 119, n->inlines[1],
                            n->owner_origin);
            return;
        }
        set_bits(word, base, 25, 16, n->bitmap_id);
        set_bits(word, base, 41, 22, n->ni_base);
        if (n->type == 1) {
            for (int i = 0; i < 2; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < static_cast<int>(n->children.size()))
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 63 + i * 32, 32, raw);
            }
        } else if (n->type == 2) {
            for (int i = 0; i < 6; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < static_cast<int>(n->children.size()))
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 63 + i * 32, 32, raw);
            }
        } else {
            set_bits(word, base, 63, 64, n->bulk_bitmap);
            set_bits(word, base, 127, 22, n->bulk_base);
            set_bits(word, base, 149, 4, n->bulk_stage);
            for (int i = 0; i < 3; ++i) {
                uint32_t raw = ABSENT_CHILD;
                if (i < n->direct_count)
                    raw = pack_child(n->child_keys[i], n->children[i]);
                set_bits(word, base, 153 + i * 32, 32, raw);
            }
        }
    }

    void fill_banks(ImageData& out) {
        std::vector<IPPrefix> sorted = prefixes_;
        std::sort(sorted.begin(), sorted.end(), prefix_entry_less);
        for (BuildNode* n : nodes_) n->bmp = bmp_for(n, sorted);

        std::vector<uint32_t> cell_count(RAM_NUM, 0);
        for (BuildNode* n : nodes_)
            if (n->cell + 1 >= cell_count[n->stage])
                cell_count[n->stage] = n->cell + 1;
        for (BuildNode* n : nodes_) {
            if (n->bulk_parent && (n->type == 1 || n->type == 4))
                cell_count[n->stage] = std::max(cell_count[n->stage],
                                                n->cell + 2);
        }
        for (int s = 0; s < RAM_NUM; ++s) {
            out.cells[s] = cell_count[s];
            out.banks[s].assign((cell_count[s] + 1) / 2,
                                std::bitset<256>());
        }
        for (BuildNode* n : nodes_) {
            std::bitset<256>& word = out.banks[n->stage][n->cell >> 1];
            pack_node(out, word, n);
        }
        out.bitmaps = bitmaps_;
        out.nexthops = nexthops_;
    }

    std::vector<uint64_t> bitmaps_;
    std::vector<uint32_t> nexthops_;
};

} // namespace

ImageData build_image(const std::vector<IPPrefix>& prefixes) {
    ImageBuilder builder(prefixes);
    return builder.run();
}

bool MemoryImage::load(const ImageData& proposed) {
    std::vector<IPPrefix> decoded;
    if (!validate_image_data(proposed, decoded)) return false;
    FibTable next;
    for (const IPPrefix& p : decoded)
        next.put(p.address, p.length, p.hop);
    data_ = proposed;
    table_ = std::move(next);
    return true;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    return table_.lookup(ip);
}
